args.new_string:
#include <string.h>
#include <iostream>
#include "blkio.h"
#include "file.h"

/* bucket b of a hash-partitioned relation occupies blocks [addr + b*BUCKET_SPACING, ...) */
#define BUCKET_SPACING 100

/* Flush the accumulated items into one disk block.
 * The block layout mirrors the relation format: items first, then zero
 * padding, with the next-block address stored in the last 4 bytes
 * (0 when this is the last block of the stream).
 */
static void flushWriteBlock(Buffer *buf, unsigned char *acc, size_t itemSize, size_t count, unsigned int addr, int last)
{
	unsigned char block[BLK_SIZE];
	unsigned char *blk;

	memset(block, 0, sizeof(block));
	memcpy(block, acc, count * itemSize);
	*(int *)(block + BLK_SIZE - sizeof(int)) = last ? 0 : (int)(addr + 1);

	blk = getNewBlockInBuffer(buf);
	memcpy(blk, block, BLK_SIZE);
	writeBlockToDisk(blk, addr, buf);
}

void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
	static unsigned char acc[BLK_SIZE]; /* in-memory accumulation area */
	static size_t itemSize = 0;
	static size_t count = 0;
	static unsigned int nextAddr = 0;
	size_t cap;

	if (reset)
	{
		itemSize = 0;
		count = 0;
		nextAddr = addr;
		return;
	}

	if (source != NULL && size > 0)
	{
		if (itemSize == 0)
			itemSize = size;
		cap = (BLK_SIZE - 2 * sizeof(int)) / itemSize;
		memcpy(acc + count * itemSize, source, itemSize);
		count++;
		if (count == cap)
		{
			flushWriteBlock(buf, acc, itemSize, count, nextAddr, 0);
			nextAddr++;
			count = 0;
		}
	}

	if (push && count > 0)
	{
		flushWriteBlock(buf, acc, itemSize, count, nextAddr, 1);
		count = 0;
	}
}

