args.new_string:
/* Flush one bucket block: HASH_PER_BLK tuple slots, followed by the valid
 * tuple count and the address of the next block of the bucket (0 if last).
 */
static void flushHashBlock(Buffer *buf, Relation *acc, int count, unsigned int addr, int last)
{
	unsigned char block[BLK_SIZE];
	unsigned char *blk;

	memset(block, 0, sizeof(block));
	memcpy(block, acc, count * sizeof(Relation));
	*(int *)(block + HASH_PER_BLK * sizeof(Relation)) = count;
	*(int *)(block + HASH_PER_BLK * sizeof(Relation) + sizeof(int)) = last ? 0 : (int)(addr + 1);

	blk = getNewBlockInBuffer(buf);
	memcpy(blk, block, BLK_SIZE);
	writeBlockToDisk(blk, addr, buf);
}

void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
{
	static Relation acc[BUCKET_NUM][HASH_PER_BLK]; /* per-bucket accumulation areas */
	static int count[BUCKET_NUM];
	static unsigned int nextAddr[BUCKET_NUM];
	int b;

	if (reset)
	{
		for (b = 0; b < BUCKET_NUM; b++)
		{
			count[b] = 0;
			nextAddr[b] = addr + b * BUCKET_SPACING;
		}
		return;
	}

	if (push)
	{
		for (b = 0; b < BUCKET_NUM; b++)
		{
			if (count[b] > 0)
			{
				flushHashBlock(buf, acc[b], count[b], nextAddr[b], 1);
				count[b] = 0;
			}
		}
		return;
	}

	b = R->attr1 % BUCKET_NUM;
	acc[b][count[b]++] = *R;
	if (count[b] == HASH_PER_BLK)
	{
		flushHashBlock(buf, acc[b], count[b], nextAddr[b], 0);
		nextAddr[b]++;
		count[b] = 0;
	}
}

