{
	int count = *(int *)(blk + HASH_PER_BLK * sizeof(Relation));
	int i;

	for (i = 0; i < count; i++)
	{
		R[i].attr1 = *(int *)(blk + i * sizeof(Relation));
		R[i].attr2 = *(int *)(blk + i * sizeof(Relation) + sizeof(int));
	}

	return count;
