using namespace std;

int select(Buffer *buf)
{
	/* reset the output stream starting at SELECT_RET_ADDR */
	pushToWrite(buf, NULL, 0, SELECT_RET_ADDR, true);

	/* STAGE 1: selection_scan_r -- scan R, keep tuples with attr1 == 40 */
	Relation t[TUPLE_PER_BLK];
	for (int addr = R_ADDR; addr < R_ADDR + R_BLK_NUM; addr++) {
		unsigned char *blk = readBlockFromDisk(addr, buf);
		readTuplesFromBlock(blk, t);
		for (int i = 0; i < TUPLE_PER_BLK; i++) {
			if (t[i].attr1 == 40) {
				cout << t[i].attr1 << " " << t[i].attr2 << endl;
				pushToWrite(buf, (unsigned char *)&t[i], sizeof(Relation), SELECT_RET_ADDR);
			}
		}
		freeBlockInBuffer(blk, buf);
	}

	/* TODO(stage 2, selection_operator): scan S (blocks S_ADDR..S_ADDR+S_BLK_NUM-1),
	 * keep tuples with attr1 == 60 (same print/pushToWrite pattern as above),
	 * then flush the tail block with
	 * pushToWrite(buf, NULL, 0, SELECT_RET_ADDR, false, true); */
	return 0;
}

