7	#include "blkio.h"
8	#include "file.h"
9	
10	/* bucket b of a hash-partitioned relation occupies blocks [addr + b*BUCKET_SPACING, ...) */
11	#define BUCKET_SPACING 100
12	
13	/* Flush the accumulated items into one disk block.
14	 * The block layout mirrors the relation format: items first, then zero
15	 * padding, with the next-block address stored in the last 4 bytes
16	 * (0 when this is the last block of the stream).
17	 */
18	static void flushWriteBlock(Buffer *buf, unsigned char *acc, size_t itemSize, size_t count, unsigned int addr, int last)
19	{
20		unsigned char block[BLK_SIZE];
21		unsigned char *blk;
22	
23		memset(block, 0, sizeof(block));
24		memcpy(block, acc, count * itemSize);
25		*(int *)(block + BLK_SIZE - sizeof(int)) = last ? 0 : (int)(addr + 1);
26	
27		blk = getNewBlockInBuffer(buf);
28		memcpy(blk, block, BLK_SIZE);
29		writeBlockToDisk(blk, addr, buf);
30	}
31	
32	void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
33	{
34		static unsigned char acc[BLK_SIZE]; /* in-memory accumulation area */
35		static size_t itemSize = 0;
36		static size_t count = 0;
37		static unsigned int nextAddr = 0;
38		size_t cap;
39	
40		if (reset)
41		{
42			itemSize = 0;
43			count = 0;
44			nextAddr = addr;
45			return;
46		}
47	
48		if (source != NULL && size > 0)
49		{
50			if (itemSize == 0)
51				itemSize = size;
52			cap = (BLK_SIZE - 2 * sizeof(int)) / itemSize;
53			memcpy(acc + count * itemSize, source, itemSize);
54			count++;
55			if (count == cap)
56			{
57				flushWriteBlock(buf, acc, itemSize, count, nextAddr, 0);
58				nextAddr++;
59				count = 0;
60			}
61		}
62	
63		if (push && count > 0)
64		{
65			flushWriteBlock(buf, acc, itemSize, count, nextAddr, 1);
66			count = 0;
67		}
68	}
