101		memset(block, 0, sizeof(block));
102		memcpy(block, acc, count * sizeof(Relation));
103		*(int *)(block + HASH_PER_BLK * sizeof(Relation)) = count;
104		*(int *)(block + HASH_PER_BLK * sizeof(Relation) + sizeof(int)) = last ? 0 : (int)(addr + 1);
105	
106		blk = getNewBlockInBuffer(buf);
107		memcpy(blk, block, BLK_SIZE);
108		writeBlockToDisk(blk, addr, buf);
