112	{
113		static Relation acc[BUCKET_NUM][HASH_PER_BLK]; /* per-bucket accumulation areas */
114		static int count[BUCKET_NUM];
115		static unsigned int nextAddr[BUCKET_NUM];
116		int b;
117	
118		if (reset)
119		{
120			for (b = 0; b < BUCKET_NUM; b++)
121			{
122				count[b] = 0;
123				nextAddr[b] = addr + b * BUCKET_SPACING;
124			}
125			return;
126		}
127	
128		if (push)
129		{
130			for (b = 0; b < BUCKET_NUM; b++)
131			{
132				if (count[b] > 0)
133				{
134					flushHashBlock(buf, acc[b], count[b], nextAddr[b], 1);
135					count[b] = 0;
136				}
137			}
138			return;
139		}
140	
141		b = R->attr1 % BUCKET_NUM;
142		acc[b][count[b]++] = *R;
143		if (count[b] == HASH_PER_BLK)
144		{
