#include <iostream>
#include <math.h>
#include "join.h"
#include "file.h"
#include "blkio.h"

using namespace std;

int nestedLoopJoin(Buffer *buf)
{
	/* reset the output stream starting at NLJ_RET_ADDR */
	pushToWrite(buf, NULL, 0, NLJ_RET_ADDR, true);

	/* STAGE 1: nested_loop_outer_scan -- load R into memory in groups of
	 * M-1 = 7 blocks, keeping their buffer slots held during the inner phase */
	int M = buf->numAllBlk;
	for (int base = 0; base < R_BLK_NUM; base += M - 1) {
		unsigned char *rBlk[M - 1];
		Relation rBuf[M - 1][TUPLE_PER_BLK];
		int groupSize = 0;
		for (int i = 0; i < M - 1 && base + i < R_BLK_NUM; i++) {
			rBlk[i] = readBlockFromDisk(base + i, buf);
			readTuplesFromBlock(rBlk[i], rBuf[i]);
			groupSize++;
		}

		/* TODO(stage 2, nested_loop_join): inner probe -- for each S block
		 * s in S_ADDR..S_ADDR+S_BLK_NUM-1, readBlockFromDisk(s, buf) into the
		 * transient 8th slot, decode it, collect all matches
		 * (rBuf[i][j].attr1 == sT[k].attr1) into a Relation3 array, free the
		 * S block, then emit each match via
		 * output(buf, NLJ_RET_ADDR, m.attr1, m.attr2, m.attr3); */

		/* release the held R blocks of this group */
		for (int i = 0; i < groupSize; i++)
			freeBlockInBuffer(rBlk[i], buf);
	}

	/* TODO(stage 2, nested_loop_join): flush the tail block with
	 * pushToWrite(buf, NULL, 0, NLJ_RET_ADDR, false, true); */
	return 0;
}

