#include <iostream>
#include <cstring>
#include "join.h"
#include "file.h"
#include "blkio.h"
#include "mergeSort.h"

using namespace std;

int sortMergeJoin(Buffer *buf)
{
	/* ---- stage 1: sort_merge_preparation ---- */

	/* Sort R and S with the external merge sort.
	 * Sorted R is chained from MERGE_R_RET_ADDR (16 blocks),
	 * sorted S from MERGE_S_RET_ADDR (32 blocks). */
	mergeSort(buf, SORT_R);
	mergeSort(buf, SORT_S);

	/* Reset the result writer stream for the join output. */
	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, true);

	/* Load the first block of each sorted relation and hold both slots. */
	unsigned char *rBlk = readBlockFromDisk(MERGE_R_RET_ADDR, buf);
	unsigned char *sBlk = readBlockFromDisk(MERGE_S_RET_ADDR, buf);

	Relation rT[TUPLE_PER_BLK];
	Relation sT[TUPLE_PER_BLK];
	readTuplesFromBlock(rBlk, rT);
	readTuplesFromBlock(sBlk, sT);

	int rPos = 0;
	int sPos = 0;
	bool rEnd = (rBlk == NULL);
	bool sEnd = (sBlk == NULL);

	/* Duplicate-key groups collected during the merge scan. */
	Relation rg[R_NUM];
	Relation sg[S_NUM];

	(void)rPos; (void)sPos; (void)rEnd; (void)sEnd; (void)rg; (void)sg;

	/* TODO(stage 2: sort_merge_join): classic two-pointer merge scan.
	 * - while both sides unexhausted:
	 *     if rT[rPos].attr1 < sT[sPos].attr1 -> advance R cursor
	 *     if rT[rPos].attr1 > sT[sPos].attr1 -> advance S cursor
	 *     on equality with key k: collect the full R group into rg and
	 *     the full S group into sg (advancing across chained blocks via
	 *     the next-pointer at offset 60), then emit the cross product
	 *     via output(buf, SMJ_RET_ADDR, k, rg[i].attr2, sg[j].attr2).
	 * - advancing a cursor: pos++; at TUPLE_PER_BLK read the next-block
	 *   address, freeBlockInBuffer the held block, read the next block
	 *   (or mark the side exhausted when next == 0) and decode it.
	 * - after the scan: free any still-held blocks, then
	 *   pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, false, true). */
	return 0;
}

