	/* STAGE 1 (hash_partitioning): partition R on attr1 % BUCKET_NUM */
	pushHashToWrite(buf, NULL, HASH_R_ADDR, true);
	for (int addr = R_ADDR; addr < R_ADDR + R_BLK_NUM; addr++) {
		unsigned char *blk = readBlockFromDisk(addr, buf);
		readTuplesFromBlock(blk, t);
		for (int i = 0; i < TUPLE_PER_BLK; i++) {
			pushHashToWrite(buf, &t[i], HASH_R_ADDR);
		}
		freeBlockInBuffer(blk, buf);
	}
	pushHashToWrite(buf, NULL, HASH_R_ADDR, false, true);

	/* partition S identically */
	pushHashToWrite(buf, NULL, HASH_S_ADDR, true);
	for (int addr = S_ADDR; addr < S_ADDR + S_BLK_NUM; addr++) {
