		readTuplesFromBlock(blk, t);
		for (int i = 0; i < TUPLE_PER_BLK; i++) {
			pushHashToWrite(buf, &t[i], HASH_S_ADDR);
		}
		freeBlockInBuffer(blk, buf);
	}
	pushHashToWrite(buf, NULL, HASH_S_ADDR, false, true);

	/* TODO(stage 2, hash_join): for each bucket b in 0..BUCKET_NUM-1, load R's
	 * bucket (chain from HASH_R_ADDR + b*100) fully into a memory array, then
	 * stream S's bucket (chain from HASH_S_ADDR + b*100) block by block; for
