//
// Created by zl on 2023/12/12.
//

#include <iostream>
#include <unistd.h>
#include "join.h"
#include "file.h"
#include "blkio.h"

using namespace std;

int hashJoin(Buffer *buf)
{
	Relation t[TUPLE_PER_BLK];

	/* phase 1: partition R on attr1 % BUCKET_NUM */
	pushHashToWrite(buf, NULL, HASH_R_ADDR, true);
	for (int addr = R_ADDR; addr < R_ADDR + R_BLK_NUM; addr++) {
		unsigned char *blk = readBlockFromDisk(addr, buf);
		readTuplesFromBlock(blk, t);
		for (int i = 0; i < TUPLE_PER_BLK; i++) {
			pushHashToWrite(buf, &t[i], HASH_R_ADDR);
		}
		freeBlockInBuffer(blk, buf);
	}
	pushHashToWrite(buf, NULL, HASH_R_ADDR, false, true);

	/* partition S identically */
	pushHashToWrite(buf, NULL, HASH_S_ADDR, true);
	for (int addr = S_ADDR; addr < S_ADDR + S_BLK_NUM; addr++) {
		unsigned char *blk = readBlockFromDisk(addr, buf);
		readTuplesFromBlock(blk, t);
		for (int i = 0; i < TUPLE_PER_BLK; i++) {
			pushHashToWrite(buf, &t[i], HASH_S_ADDR);
		}
		freeBlockInBuffer(blk, buf);
	}
	pushHashToWrite(buf, NULL, HASH_S_ADDR, false, true);

	/* phase 2: per-bucket join, result tuples (A, B, D) to HJ_RET_ADDR */
	pushToWrite(buf, NULL, 0, HJ_RET_ADDR, true);

	for (int b = 0; b < BUCKET_NUM; b++) {
		Relation rBuf[R_NUM];
		int rCount = 0;

		/* load R's bucket b fully into memory */
		unsigned int addr = HASH_R_ADDR + b * 100;
		while (addr != 0) {
			unsigned char *blk = readBlockFromDisk(addr, buf);
			rCount += readHashFromBlock(blk, rBuf + rCount);
			addr = *(int *)(blk + HASH_PER_BLK * sizeof(Relation) + sizeof(int));
			freeBlockInBuffer(blk, buf);
		}

		/* stream S's bucket b, probing rBuf for each tuple */
		addr = HASH_S_ADDR + b * 100;
		while (addr != 0) {
			unsigned char *blk = readBlockFromDisk(addr, buf);
			Relation sBuf[HASH_PER_BLK];
			int sCount = readHashFromBlock(blk, sBuf);
			int next = *(int *)(blk + HASH_PER_BLK * sizeof(Relation) + sizeof(int));
			for (int i = 0; i < sCount; i++) {
				for (int j = 0; j < rCount; j++) {
					if (rBuf[j].attr1 == sBuf[i].attr1) {
						output(buf, HJ_RET_ADDR, rBuf[j].attr1, rBuf[j].attr2, sBuf[i].attr2);
					}
				}
			}
			freeBlockInBuffer(blk, buf);
			addr = next;
		}
	}

	pushToWrite(buf, NULL, 0, HJ_RET_ADDR, false, true);
	return 0;
}

