#include <iostream>
#include <math.h>
#include "join.h"
#include "file.h"
#include "blkio.h"

using namespace std;

int nestedLoopJoin(Buffer *buf)
{
	/* reset the output stream starting at NLJ_RET_ADDR */
	pushToWrite(buf, NULL, 0, NLJ_RET_ADDR, true);

	/* STAGE 1: nested_loop_outer_scan -- load R into memory in groups of
	 * M-1 = 7 blocks, keeping their buffer slots held during the inner phase */
	int M = buf->numAllBlk;
	for (int base = 0; base < R_BLK_NUM; base += M - 1) {
		unsigned char *rBlk[7];
		Relation rBuf[7][TUPLE_PER_BLK];
		int groupSize = 0;
		for (int i = 0; i < M - 1 && base + i < R_BLK_NUM; i++) {
			rBlk[i] = readBlockFromDisk(base + i, buf);
			readTuplesFromBlock(rBlk[i], rBuf[i]);
			groupSize++;
		}

		/* STAGE 2: nested_loop_join -- inner probe over S.  The S block
		 * occupies the transient 8th slot; it is freed BEFORE emitting so a
		 * free slot is guaranteed for pushToWrite's output flush. */
		for (int s = S_ADDR; s < S_ADDR + S_BLK_NUM; s++) {
			unsigned char *sBlk = readBlockFromDisk(s, buf);
			Relation sT[TUPLE_PER_BLK];
			readTuplesFromBlock(sBlk, sT);

			Relation3 matches[7 * TUPLE_PER_BLK * TUPLE_PER_BLK];
			int matchNum = 0;
			for (int i = 0; i < groupSize; i++)
				for (int j = 0; j < TUPLE_PER_BLK; j++)
					for (int k = 0; k < TUPLE_PER_BLK; k++)
						if (rBuf[i][j].attr1 == sT[k].attr1) {
							matches[matchNum].attr1 = rBuf[i][j].attr1;
							matches[matchNum].attr2 = rBuf[i][j].attr2;
							matches[matchNum].attr3 = sT[k].attr2;
							matchNum++;
						}

			freeBlockInBuffer(sBlk, buf);

			for (int m = 0; m < matchNum; m++)
				output(buf, NLJ_RET_ADDR, matches[m].attr1, matches[m].attr2,
				       matches[m].attr3);
		}

		/* release the held R blocks of this group */
		for (int i = 0; i < groupSize; i++)
			freeBlockInBuffer(rBlk[i], buf);
	}

	/* flush the partial tail block of the result stream */
	pushToWrite(buf, NULL, 0, NLJ_RET_ADDR, false, true);
	return 0;
}

