#include <iostream>
#include <string>
#include <vector>
#include "tree.h"

using namespace std;

void parseQuery(TreeNode *root, string query);
TreeNode *optimizeQuery(TreeNode *root, vector<string> info);

int main()
{
	string query1 = "SELECT [ ENAME = 'Mary' & DNAME = 'Research' ] ( EMPLOYEE JOIN DEPARTMENT )";
	string query2 = "PROJECTION [ BDATE ] ( SELECT [ ENAME = 'John' & DNAME = 'Research' ] ( EMPLOYEE JOIN DEPARTMENT ) )";
	string query3 = "SELECT [ ESSN = '01' ] ( PROJECTION [ ESSN, PNAME ] ( WORKS_ON JOIN PROJECT ) )";
	string query[3] = { query1, query2, query3 };

	for (int i = 0; i < 3; i++) {
		cout << "Query " << i + 1 << ":" << endl << endl;
		TreeNode *root = new TreeNode(); // root node does not store any information
		parseQuery(root, query[i]);
		root->left->preOrder(0);
		cout << endl;
		root->left = optimizeQuery(root->left, vector<string>());
		root->left->preOrder(0);
		cout << endl;
	}

	return 0;
}

static bool isSpaceChar(char c)
{
	return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

static bool isWordChar(char c)
{
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
	       (c >= '0' && c <= '9') || c == '_';
}

static void skipSpaces(const string &s, size_t &pos)
{
	while (pos < s.size() && isSpaceChar(s[pos]))
		pos++;
}

static string readWord(const string &s, size_t &pos)
{
	skipSpaces(s, pos);
	size_t start = pos;
	while (pos < s.size() && isWordChar(s[pos]))
		pos++;
	return s.substr(start, pos - start);
}

static string trimStr(const string &s)
{
	size_t b = s.find_first_not_of(" \t\n\r");
	if (b == string::npos)
		return "";
	size_t e = s.find_last_not_of(" \t\n\r");
	return s.substr(b, e - b + 1);
}

static TreeNode *parseExpr(const string &s, size_t &pos);

// operand := '(' expr ')' | IDENT
static TreeNode *parseOperand(const string &s, size_t &pos)
{
	skipSpaces(s, pos);
	if (pos < s.size() && s[pos] == '(') {
		pos++;
		TreeNode *node = parseExpr(s, pos);
		skipSpaces(s, pos);
		if (pos < s.size() && s[pos] == ')')
			pos++;
		return node;
	}
	return new TreeNode("LEAF", readWord(s, pos));
}

// expr := ('SELECT'|'PROJECTION') '[' info ']' '(' expr ')' | operand ( 'JOIN' operand )*
static TreeNode *parseExpr(const string &s, size_t &pos)
{
	skipSpaces(s, pos);
	size_t save = pos;
	string word = readWord(s, pos);
	if (word == "SELECT" || word == "PROJECTION") {
		skipSpaces(s, pos);
		size_t start = pos;
		if (pos < s.size() && s[pos] == '[') {
			start = ++pos;
			while (pos < s.size() && s[pos] != ']')
				pos++;
		}
		string info = trimStr(s.substr(start, pos - start));
		if (pos < s.size() && s[pos] == ']')
			pos++;
		skipSpaces(s, pos);
		if (pos < s.size() && s[pos] == '(')
			pos++;
		TreeNode *node = new TreeNode(word, info);
		node->left = parseExpr(s, pos);
		skipSpaces(s, pos);
		if (pos < s.size() && s[pos] == ')')
			pos++;
		return node;
	}
	pos = save;
	TreeNode *left = parseOperand(s, pos);
	while (true) {
		skipSpaces(s, pos);
		size_t before = pos;
		if (readWord(s, pos) != "JOIN") {
			pos = before;
			break;
		}
		TreeNode *node = new TreeNode("JOIN");
		node->left = left;
		node->right = parseOperand(s, pos);
		left = node;
	}
	return left;
}

void parseQuery(TreeNode *root, string query)
{
	size_t pos = 0;
	root->left = parseExpr(query, pos);
}

// split a SELECT info string on '&', trimming each predicate
static vector<string> splitPreds(const string &s)
{
	vector<string> out;
	size_t start = 0;
	while (true) {
		size_t amp = s.find('&', start);
		string part = trimStr(amp == string::npos
			? s.substr(start)
			: s.substr(start, amp - start));
		if (!part.empty())
			out.push_back(part);
		if (amp == string::npos)
			break;
		start = amp + 1;
	}
	return out;
}

// collect the info strings (relation names) of all LEAF nodes under root
static void collectLeaves(TreeNode *root, vector<string> &leaves)
{
	if (root == NULL)
		return;
	if (root->type == "LEAF")
		leaves.push_back(root->info);
	collectLeaves(root->left, leaves);
	collectLeaves(root->right, leaves);
}

// attribute name of a predicate: first token before whitespace or '='
static string predAttr(const string &pred)
{
	size_t end = pred.find_first_of(" \t=");
	return pred.substr(0, end);
}

// wrap preds as a SELECT chain above base (last predicate innermost,
// first predicate outermost) and return the chain top
static TreeNode *wrapSelects(TreeNode *base, const vector<string> &preds)
{
	TreeNode *top = base;
	for (int i = (int)preds.size() - 1; i >= 0; i--) {
		TreeNode *node = new TreeNode("SELECT", preds[i]);
		node->left = top;
		top = node;
	}
	return top;
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	if (root == NULL)
		return NULL;
	if (root->type == "SELECT") {
		vector<string> next = info;
		vector<string> parts = splitPreds(root->info);
		next.insert(next.end(), parts.begin(), parts.end());
		return optimizeQuery(root->left, next);
	}
	if (root->type == "PROJECTION") {
		root->left = optimizeQuery(root->left, info);
		return root;
	}
	if (root->type == "JOIN") {
		vector<string> leftLeaves, rightLeaves;
		collectLeaves(root->left, leftLeaves);
		collectLeaves(root->right, rightLeaves);
		vector<string> leftPreds, rightPreds, keep;
		for (size_t i = 0; i < info.size(); i++) {
			string attr = predAttr(info[i]);
			char c = attr.empty() ? '\0' : attr[0];
			bool inLeft = false, inRight = false;
			for (size_t j = 0; j < leftLeaves.size(); j++)
				if (!leftLeaves[j].empty() && leftLeaves[j][0] == c)
					inLeft = true;
			for (size_t j = 0; j < rightLeaves.size(); j++)
				if (!rightLeaves[j].empty() && rightLeaves[j][0] == c)
					inRight = true;
			if (inLeft && !inRight)
				leftPreds.push_back(info[i]);
			else if (inRight && !inLeft)
				rightPreds.push_back(info[i]);
			else
				keep.push_back(info[i]);
		}
		root->left = optimizeQuery(root->left, leftPreds);
		root->right = optimizeQuery(root->right, rightPreds);
		return wrapSelects(root, keep);
	}
	// LEAF: all inherited predicates apply here
	return wrapSelects(root, info);
}

