//
// Created by zl on 2023/12/11.
//

#include <iostream>
#include <string.h>
#include <algorithm>
#include <cmath>
#include "mergeSort.h"
#include "file.h"
#include "blkio.h"

using namespace std;

/* Sort key: attr1, tie-break attr2 (deterministic). */
static bool tupleLess(const Relation &a, const Relation &b)
{
	if (a.attr1 != b.attr1)
		return a.attr1 < b.attr1;
	return a.attr2 < b.attr2;
}

/* Build one 64-byte relation block in a local memory buffer
 * (tuples, 4 zero padding bytes, next-block address at offset 60),
 * then flush it to disk through one buffer slot.
 */
static void writeRelationBlock(Buffer *buf, const Relation *tuples, int nTuples,
							   unsigned int addr, unsigned int next)
{
	unsigned char tmp[BLK_SIZE];
	unsigned char *blk;

	memset(tmp, 0, BLK_SIZE);
	memcpy(tmp, tuples, nTuples * sizeof(Relation));
	*(unsigned int *)(tmp + BLK_SIZE - PTR_SIZE) = next;

	blk = getNewBlockInBuffer(buf);
	memcpy(blk, tmp, BLK_SIZE);
	writeBlockToDisk(blk, addr, buf);
}

/* Pass 1: read the relation M blocks at a time, sort each run in
 * memory and write the sorted runs as chained blocks at segAddr.
 * Holds at most 1 buffer slot at a time.
 */
static void externalSortRuns(Buffer *buf, unsigned int baseAddr, int blkNum,
							 unsigned int segAddr, size_t M)
{
	Relation *run = new Relation[M * TUPLE_PER_BLK];
	int runNum = (blkNum + (int)M - 1) / (int)M;
	int i, j;

	for (i = 0; i < runNum; i++)
	{
		int nBlks = (int)M < blkNum - i * (int)M ? (int)M : blkNum - i * (int)M;

		for (j = 0; j < nBlks; j++)
		{
			unsigned char *blk = readBlockFromDisk(baseAddr + i * M + j, buf);
			readTuplesFromBlock(blk, run + j * TUPLE_PER_BLK);
			freeBlockInBuffer(blk, buf);
		}

		sort(run, run + nBlks * TUPLE_PER_BLK, tupleLess);

		for (j = 0; j < nBlks; j++)
		{
			unsigned int next = (j + 1 < nBlks) ? segAddr + i * M + j + 1 : 0;
			writeRelationBlock(buf, run + j * TUPLE_PER_BLK, TUPLE_PER_BLK,
							   segAddr + i * M + j, next);
		}
	}

	delete[] run;
}

/* Pass 2: k-way merge of the k sorted runs (k <= M - 1) into the
 * final sorted relation at retAddr. Holds one buffer slot per run
 * plus one transient slot for output flushes (k + 1 <= M).
 */
static void externalMerge(Buffer *buf, unsigned int segAddr, int blkNum,
						  unsigned int retAddr, int totalTuples, size_t M)
{
	int k = (blkNum + (int)M - 1) / (int)M;
	unsigned char **blkPtr = new unsigned char *[k];
	Relation *runTuples = new Relation[k * TUPLE_PER_BLK];
	int *pos = new int[k];
	bool *active = new bool[k];
	Relation out[TUPLE_PER_BLK];
	int outCnt = 0;
	int outBlk = 0;
	int emitted, i;

	/* Open the first block of every run. */
	for (i = 0; i < k; i++)
	{
		blkPtr[i] = readBlockFromDisk(segAddr + i * M, buf);
		readTuplesFromBlock(blkPtr[i], runTuples + i * TUPLE_PER_BLK);
		pos[i] = 0;
		active[i] = true;
	}

	for (emitted = 0; emitted < totalTuples; emitted++)
	{
		int best = -1;

		for (i = 0; i < k; i++)
		{
			if (!active[i])
				continue;
			if (best < 0 ||
				tupleLess(runTuples[i * TUPLE_PER_BLK + pos[i]],
						  runTuples[best * TUPLE_PER_BLK + pos[best]]))
				best = i;
		}

		out[outCnt++] = runTuples[best * TUPLE_PER_BLK + pos[best]];
		pos[best]++;

		if (pos[best] == TUPLE_PER_BLK)
		{
			unsigned int next = *(unsigned int *)(blkPtr[best] + BLK_SIZE - PTR_SIZE);

			freeBlockInBuffer(blkPtr[best], buf);
			if (next == 0)
			{
				active[best] = false;
			}
			else
			{
				blkPtr[best] = readBlockFromDisk(next, buf);
				readTuplesFromBlock(blkPtr[best], runTuples + best * TUPLE_PER_BLK);
				pos[best] = 0;
			}
		}

		if (outCnt == TUPLE_PER_BLK)
		{
			unsigned int next;

			outBlk++;
			next = (outBlk * TUPLE_PER_BLK >= totalTuples) ? 0 : retAddr + outBlk;
			writeRelationBlock(buf, out, TUPLE_PER_BLK, retAddr + outBlk - 1, next);
			outCnt = 0;
		}
	}

	delete[] blkPtr;
	delete[] runTuples;
	delete[] pos;
	delete[] active;
}

int mergeSort(Buffer *buf, bool choice)
{
