	int blkNum = (choice == SORT_R) ? R_BLK_NUM : S_BLK_NUM;
	int totalTuples = (choice == SORT_R) ? R_NUM : S_NUM;
	unsigned int segAddr = (choice == SORT_R) ? MERGE_R_SEG_ADDR : MERGE_S_SEG_ADDR;
