			flushHashBlock(buf, acc[b], count[b], nextAddr[b], 1);
			count[b] = 0;
		}
		else if (nextAddr[b] > baseAddr + b * BUCKET_SPACING)
		{
			/* bucket length was an exact multiple of HASH_PER_BLK */
			terminateChain(buf, nextAddr[b] - 1,
				HASH_PER_BLK * sizeof(Relation) + sizeof(int));
		}
	}
	return;
}
